def find_golomb_ruler(n=8, fixed=None, max_length=200):
    # fixed: dict index->value
    if fixed is None:
        fixed = {}
    marks = [None]*n
    # set fixed
    for i,v in fixed.items():
        marks[i]=v
    # ensure first is 0
    if marks[0] is None:
        marks[0]=0
    # distances set
    dists=set()

    # backtrack function
    def backtrack(idx):
        if idx==n:
            # check all distances distinct (already ensured)
            return True
        if marks[idx] is not None:
            # check distances with previous marks
            val = marks[idx]
            for j in range(idx):
                d = val - marks[j]
                if d in dists:
                    return False
            # add distances
            for j in range(idx):
                dists.add(val-marks[j])
            if backtrack(idx+1):
                return True
            # remove distances
            for j in range(idx):
                dists.remove(val-marks[j])
            return False

        # try values
        start = marks[idx-1]+1 if idx>0 else 0
        # if we have a fixed later mark, we might need to bound?
        # just search up to max_length
        for val in range(start, max_length+1):
            # check distances
            ok=True
            new_dists=[]
            for j in range(idx):
                d = val - marks[j]
                if d in dists:
                    ok=False
                    break
                new_dists.append(d)
            if not ok:
                continue
            # add
            marks[idx]=val
            for d in new_dists:
                dists.add(d)
            if backtrack(idx+1):
                return True
            # remove
            for d in new_dists:
                dists.remove(d)
            marks[idx]=None
        return False

    # pre-add fixed distances
    # Actually easier: just run backtrack from 0
    # But need to handle fixed marks properly
    # Let's just run from 0
    if backtrack(0):
        return marks
    else:
        return None

